"""Generate a local-only review directory; this page is not part of production routes."""
import json,html
from pathlib import Path
root=Path(__file__).resolve().parents[2];items=json.loads((root/'src/featured.json').read_text())
style='''*{box-sizing:border-box}body{margin:0;background:#eeede6;color:#26332b;font-family:"Helvetica Neue","PingFang SC",sans-serif}main{max-width:1440px;margin:auto;padding:54px 5vw 80px}header{border-bottom:1px solid #26332b40;padding-bottom:28px;margin-bottom:30px}.brand{font-size:14px}h1{font-family:"Bodoni 72","Songti SC",serif;font-weight:400;font-size:clamp(36px,5vw,64px);line-height:1.12;margin:22px 0 16px}header p{line-height:1.8;max-width:720px;font-size:15px}nav{display:flex;gap:18px;font-size:14px}a{color:inherit}section{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:28px 20px}.product{text-decoration:none;display:block}.visual{aspect-ratio:4/3;display:grid;place-items:center;border-radius:12px;overflow:hidden}.visual img{width:80%;height:85%;object-fit:contain}.number{font-size:12px;opacity:.65;margin-top:15px}h2{font-size:18px;font-weight:500;line-height:1.35;margin:7px 0}article p{font-size:13px;line-height:1.5;margin:5px 0 11px;opacity:.75}.action{font-size:13px;text-decoration:underline;text-underline-offset:4px}.product:hover .visual{outline:1px solid #26332b70}.product:focus-visible{outline:2px solid #26332b;outline-offset:5px}footer{margin-top:45px;font-size:13px;line-height:1.8;border-top:1px solid #26332b40;padding-top:20px}@media(max-width:900px){section{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:32px 20px 50px}h2{font-size:16px}}'''
cards=[]
for i,p in enumerate(items):
 cards.append(f'''<article><a class="product" href="/?model={p['id']}"><div class="visual" style="background:{p['background']}"><img loading="lazy" src="/featured/{p['id']}-640.webp" alt="{html.escape(p['name'])} 参考产品"></div><div class="number">{i+1:02} / {p['id']}</div><h2>{html.escape(p['name'])}</h2><p>{html.escape(p['kind']['zh'])}</p><span class="action">打开 3D 预览</span></a></article>''')
page=f'''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>包材库 · 24款结构预览</title><style>{style}</style><main><header><div class="brand">源泽 · 本地模型预览</div><h1>首页精选 · 3D 预览</h1><p>本地预览 · 暂未上线。点击参考产品进入三维展示：拖拽旋转、滚动或滑动展开，查看盖体分层和独立 Logo 印刷层。</p><nav><a href="/">返回客户端首页</a></nav></header><section>{''.join(cards)}</section><footer>按海报制作的外观结构初稿。瓶盖内部、壁厚、尺寸及部分标签排版为示意，后续以实物和定稿文件校准。</footer></main></html>'''
(root/'public/model-review.html').write_text(page);(Path(__file__).parent/'review.html').write_text(page)
print('Local review index: 24 products')
